// #d1389638e94bd1fb2467199d — מנהל חשבון может основать НОВУЮ симуляцию на активном шаблоне, даже когда у бизнеса уже есть симуляции.
// Роли: admin (готовит свой шаблон) + business (применяет) + user (не может). Каждая роль — своё окно (asUser).
// Данные: шаблон «QA-AT QA-AUTO-…» создаётся админом через API (копия полей существующего шаблона), в конце ОТКЛЮЧАЕТСЯ
// (удаления шаблонов нет). Черновики симуляций, созданные business из шаблона, неудаляемы — остаются в бизнесе
// (имя/поля из шаблона QA-AT, статус טיוטה).
import * as path from 'path';
import { test, expect } from '../../fixtures';
import { openWithApi, runStamp, Api } from '../support/api';

test.describe.configure({ mode: 'serial' });

const ADMIN_STATE = path.resolve(__dirname, '../../../auth/admin.json');
const TEMPLATE_NAME = `QA-AT QA-AUTO-${runStamp()}`;
let templateId = '';

const templatesBlock = (page: import('@playwright/test').Page) =>
  page.getByRole('region', { name: 'להתחיל מתבנית מוכחת' });

async function setTemplateStatus(api: Api, status: 'active' | 'disabled') {
  const res = await api.rpc('admin_set_template_status', { p_template_id: templateId, p_status: status });
  expect(res.ok(), `admin_set_template_status ${status}: ${res.status()} ${await res.text()}`).toBeTruthy();
}

test.describe('Шаблоны симуляций — шаблон для любой новой симуляции (#d1389638e94bd1fb2467199d)', () => {
  test.afterAll(async ({ browser }) => {
    if (!templateId) return;
    const ctx = await browser.newContext({ storageState: ADMIN_STATE });
    try {
      const api = await openWithApi(await ctx.newPage(), '/admin/templates');
      await setTemplateStatus(api, 'disabled');
    } finally {
      await ctx.close();
    }
  });

  test('бизнес с симуляциями: на /simulations/new есть «להתחיל מתבנית מוכחת», каждое применение — отдельный черновик @desktop @data #d1389638e94bd1fb2467199d', async ({ asUser }) => {
    // admin: свой активный шаблон
    const admin = await asUser('admin');
    const adminApi = await openWithApi(admin, '/admin/templates');
    const existing = await adminApi.get('simulation_templates?select=id,name,fields&order=name.asc&limit=1');
    expect(existing.ok()).toBeTruthy();
    const [source] = (await existing.json()) as { fields: Record<string, unknown> }[];
    expect(source, 'нужен хотя бы один шаблон-источник полей').toBeTruthy();
    const saved = await adminApi.rpc('admin_save_template', { p_template_id: null, p_name: TEMPLATE_NAME, p_fields: source.fields });
    expect(saved.ok(), `admin_save_template: ${saved.status()} ${await saved.text()}`).toBeTruthy();
    const found = await adminApi.get(`simulation_templates?select=id&name=eq.${encodeURIComponent(TEMPLATE_NAME)}`);
    templateId = ((await found.json()) as { id: string }[])[0]?.id;
    expect(templateId, 'шаблон QA-AT не найден после сохранения').toBeTruthy();
    test.info().annotations.push({ type: 'test-data', description: `template ${TEMPLATE_NAME} ${templateId} (отключается в afterAll)` });
    await setTemplateStatus(adminApi, 'active');

    // business: уже есть ≥1 симуляция (суть бага — раньше выбор был только в пустом состоянии)
    const biz = await asUser('business');
    const bizApi = await openWithApi(biz, '/simulations/new');
    const before = (await (await bizApi.get('simulations?select=id')).json()) as { id: string }[];
    expect(before.length, 'предусловие: у бизнеса уже есть симуляции').toBeGreaterThan(0);

    const created: string[] = [];
    for (let i = 0; i < 2; i++) {
      if (i > 0) await biz.goto('/simulations/new');
      // Источник: «מה רצוי» — «מנהל חשבון יכול לבסס כל סימולציה חדשה על תבנית פעילה».
      const item = templatesBlock(biz).getByRole('listitem').filter({ hasText: TEMPLATE_NAME });
      await expect(item).toBeVisible();
      await item.getByRole('button', { name: 'שימוש בתבנית' }).click();
      await biz.waitForURL(/\/simulations\/[0-9a-f-]{36}/);
      created.push(biz.url().match(/\/simulations\/([0-9a-f-]{36})/)![1]);
    }
    test.info().annotations.push({ type: 'test-data', description: `drafts ${created.join(', ')} (неудаляемы)` });
    expect(created[0]).not.toBe(created[1]);

    const drafts = (await (await bizApi.get(`simulations?select=id,status&id=in.(${created.join(',')})`)).json()) as { id: string; status: string }[];
    expect(drafts).toHaveLength(2);
    for (const d of drafts) expect(d.status).toBe('draft');
    const after = (await (await bizApi.get('simulations?select=id')).json()) as { id: string }[];
    expect(after.length).toBe(before.length + 2);
  });

  test('user (מנהל/ת מגייס/ת): /simulations/new — «אין לך הרשאה למסך הזה», RPC 403 @desktop @data #d1389638e94bd1fb2467199d', async ({ asUser }) => {
    expect(templateId, 'нужен шаблон из первого теста (serial)').toBeTruthy();
    const user = await asUser('user');
    const api = await openWithApi(user, '/simulations/new');
    await expect(user.getByRole('heading', { level: 1, name: 'אין לך הרשאה למסך הזה' })).toBeVisible();
    await expect(templatesBlock(user)).toHaveCount(0);
    const res = await api.rpc('create_simulation_from_template', { p_template_id: templateId });
    expect(res.status()).toBe(403);
  });

  test('отключённый шаблон не предлагается: нет в блоке, RPC 400 template_disabled @desktop @data #d1389638e94bd1fb2467199d', async ({ asUser }) => {
    expect(templateId, 'нужен шаблон из первого теста (serial)').toBeTruthy();
    const admin = await asUser('admin');
    await setTemplateStatus(await openWithApi(admin, '/admin/templates'), 'disabled');

    const biz = await asUser('business');
    const templatesLoaded = biz.waitForResponse((r) => r.url().includes('/rest/v1/simulation_templates'));
    const api = await openWithApi(biz, '/simulations/new');
    await templatesLoaded;
    await expect(biz.getByRole('heading', { level: 1, name: 'סימולציה חדשה' })).toBeVisible();
    await expect(biz.getByText(TEMPLATE_NAME)).toHaveCount(0);

    const res = await api.rpc('create_simulation_from_template', { p_template_id: templateId });
    expect(res.status()).toBe(400);
    expect(await res.text()).toContain('template_disabled');
  });
});
